1	syntax = "proto3";
2	
3	package memos.api.v1;
4	
5	import "google/api/annotations.proto";
6	import "google/api/client.proto";
7	import "google/api/field_behavior.proto";
8	import "google/api/resource.proto";
9	import "google/protobuf/empty.proto";
10	import "google/protobuf/field_mask.proto";
11	
12	option go_package = "gen/api/v1";
13	
14	service ShortcutService {
15	  // ListShortcuts returns a user's saved shortcuts. Each shortcut is a named,
16	  // reusable CEL filter (see Shortcut.filter); pass its filter string directly
17	  // to the ListMemos `filter` argument to reuse a saved view.
18	  rpc ListShortcuts(ListShortcutsRequest) returns (ListShortcutsResponse) {
19	    option (google.api.http) = {get: "/api/v1/{parent=users/*}/shortcuts"};
20	    option (google.api.method_signature) = "parent";
21	  }
22	
23	  // GetShortcut gets a shortcut by name.
24	  rpc GetShortcut(GetShortcutRequest) returns (Shortcut) {
25	    option (google.api.http) = {get: "/api/v1/{name=users/*/shortcuts/*}"};
26	    option (google.api.method_signature) = "name";
27	  }
28	
29	  // CreateShortcut creates a new shortcut for a user.
30	  rpc CreateShortcut(CreateShortcutRequest) returns (Shortcut) {
31	    option (google.api.http) = {
32	      post: "/api/v1/{parent=users/*}/shortcuts"
33	      body: "shortcut"
34	    };
35	    option (google.api.method_signature) = "parent,shortcut";
36	  }
37	
38	  // UpdateShortcut updates a shortcut for a user.
39	  rpc UpdateShortcut(UpdateShortcutRequest) returns (Shortcut) {
40	    option (google.api.http) = {
41	      patch: "/api/v1/{shortcut.name=users/*/shortcuts/*}"
42	      body: "shortcut"
43	    };
44	    option (google.api.method_signature) = "shortcut,update_mask";
45	  }
46	
47	  // DeleteShortcut deletes a shortcut for a user.
48	  rpc DeleteShortcut(DeleteShortcutRequest) returns (google.protobuf.Empty) {
49	    option (google.api.http) = {delete: "/api/v1/{name=users/*/shortcuts/*}"};
50	    option (google.api.method_signature) = "name";
51	  }
52	}
53	
54	message Shortcut {
55	  option (google.api.resource) = {
56	    type: "memos.api.v1/Shortcut"
57	    pattern: "users/{username}/shortcuts/{shortcut}"
58	    singular: "shortcut"
59	    plural: "shortcuts"
60	  };
61	
62	  // The resource name of the shortcut.
63	  // Format: users/{username}/shortcuts/{shortcut}
64	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
65	
66	  // The title of the shortcut.
67	  string title = 2 [(google.api.field_behavior) = REQUIRED];
68	
69	  // The CEL filter expression for the shortcut, using the same grammar as the
70	  // ListMemos `filter` argument. Reuse it by passing this value to ListMemos.
71	  string filter = 3 [(google.api.field_behavior) = OPTIONAL];
72	}
73	
74	message ListShortcutsRequest {
75	  // Required. The parent resource where shortcuts are listed.
76	  // Format: users/{username}
77	  string parent = 1 [
78	    (google.api.field_behavior) = REQUIRED,
79	    (google.api.resource_reference) = {child_type: "memos.api.v1/Shortcut"}
80	  ];
81	}
82	
83	message ListShortcutsResponse {
84	  // The list of shortcuts.
85	  repeated Shortcut shortcuts = 1;
86	}
87	
88	message GetShortcutRequest {
89	  // Required. The resource name of the shortcut to retrieve.
90	  // Format: users/{username}/shortcuts/{shortcut}
91	  string name = 1 [
92	    (google.api.field_behavior) = REQUIRED,
93	    (google.api.resource_reference) = {type: "memos.api.v1/Shortcut"}
94	  ];
95	}
96	
97	message CreateShortcutRequest {
98	  // Required. The parent resource where this shortcut will be created.
99	  // Format: users/{username}
100	  string parent = 1 [
101	    (google.api.field_behavior) = REQUIRED,
102	    (google.api.resource_reference) = {child_type: "memos.api.v1/Shortcut"}
103	  ];
104	
105	  // Required. The shortcut to create.
106	  Shortcut shortcut = 2 [(google.api.field_behavior) = REQUIRED];
107	
108	  // Optional. If set, validate the request, but do not actually create the shortcut.
109	  bool validate_only = 3 [(google.api.field_behavior) = OPTIONAL];
110	}
111	
112	message UpdateShortcutRequest {
113	  // Required. The shortcut resource which replaces the resource on the server.
114	  Shortcut shortcut = 1 [(google.api.field_behavior) = REQUIRED];
115	
116	  // Optional. The list of fields to update.
117	  google.protobuf.FieldMask update_mask = 2 [(google.api.field_behavior) = OPTIONAL];
118	}
119	
120	message DeleteShortcutRequest {
121	  // Required. The resource name of the shortcut to delete.
122	  // Format: users/{username}/shortcuts/{shortcut}
123	  string name = 1 [
124	    (google.api.field_behavior) = REQUIRED,
125	    (google.api.resource_reference) = {type: "memos.api.v1/Shortcut"}
126	  ];
127	}
